// ============================================================================
// Assemble log — MITRE Chat (serveur MCP v2.2 / v3.0, 14 outils)
//
// Source des metriques : les "intermediate steps" de l'AI Agent (n8n natif).
// Le serveur n'expose PAS d'outil de metriques : rien n'est donc demande au
// serveur ici. La version du referentiel est lue dans les reponses d'outils,
// qui rappellent toutes db_version.
//
// Regle : si une donnee est absente, on ecrit null / 0 / 'unknown'.
// JAMAIS de valeur inventee — le log doit rester une preuve.
// ============================================================================

const start = $('Marque debut').item.json;
const agent = $('AI Agent').item.json;

const finishedMs = Date.now();

// ---- 1) Etapes intermediaires : quels outils, avec quels arguments ---------
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];

const toolsCalled = [];
const requestedIds = new Set();   // IDs presents dans les ARGUMENTS d'appel
const relatedIds   = new Set();   // IDs apparus dans les REPONSES
let dbEnterprise = null, dbIcs = null;

// Identifiants MITRE + fiches internes THQ
const RE_ID = /\b(?:TA\d{4}|T\d{4}(?:\.\d{3})?|M\d{4}|S\d{4}|G\d{4}|DS\d{4}|THQ\d{4})\b/g;

function idsOf(text) {
  if (!text) return [];
  const m = String(text).match(RE_ID);
  return m ? Array.from(new Set(m)) : [];
}

for (const step of steps) {
  const action = step.action || {};
  // n8n prefixe parfois le nom de l'outil : on garde le segment final.
  const rawName = action.tool || action.toolName || 'unknown';
  const toolName = String(rawName).split('__').pop();
  toolsCalled.push(toolName);

  // Arguments -> identifiants explicitement demandes par le modele
  const inputTxt = typeof action.toolInput === 'string'
    ? action.toolInput
    : JSON.stringify(action.toolInput || {});
  idsOf(inputTxt).forEach(id => requestedIds.add(id));

  // Observation -> identifiants retournes par le serveur + db_version
  const obs = typeof step.observation === 'string'
    ? step.observation
    : JSON.stringify(step.observation || '');
  idsOf(obs).forEach(id => relatedIds.add(id));

  if (!dbEnterprise) {
    try {
      const parsed = JSON.parse(obs);
      const dv = parsed && parsed.db_version;
      if (dv) { dbEnterprise = dv.Enterprise || null; dbIcs = dv.ICS || null; }
    } catch (e) {
      // Reponse non-JSON ou tronquee : on tente une lecture textuelle.
      const m = String(obs).match(/"Enterprise"\s*:\s*"([^"]+)"/);
      if (m) dbEnterprise = m[1];
      const m2 = String(obs).match(/"ICS"\s*:\s*"([^"]+)"/);
      if (m2) dbIcs = m2[1];
    }
  }
}

// Un ID demande n'est pas compte deux fois comme "related".
requestedIds.forEach(id => relatedIds.delete(id));

// ---- 2) Identifiants cites dans la reponse finale --------------------------
const answer = agent.output || '';
idsOf(answer).forEach(id => { if (!requestedIds.has(id)) relatedIds.add(id); });

// ---- 3) Liste normalisee pour la table execution_mitre_ids -----------------
function classify(id) {
  if (id.startsWith('THQ')) return 'internal';
  if (id.startsWith('TA'))  return 'tactic';
  if (id.startsWith('M'))   return 'mitigation';
  if (id.startsWith('S'))   return 'software';
  if (id.startsWith('G'))   return 'group';
  if (id.startsWith('DS'))  return 'datasource';
  return 'technique';
}
// La matrice n'est pas deductible de l'identifiant seul (sauf T0xxx = ICS).
function matrixOf(id) {
  if (/^T0\d{3}/.test(id)) return 'ICS';
  return null;
}

const mitre_ids = [
  ...Array.from(requestedIds).map(id => ({
    mitre_id: id, id_type: classify(id), matrix: matrixOf(id), relation: 'requested'
  })),
  ...Array.from(relatedIds).map(id => ({
    mitre_id: id, id_type: classify(id), matrix: matrixOf(id), relation: 'related'
  })),
];

// ---- 4) Tokens : uniquement si n8n les expose ------------------------------
const usage = agent.tokenUsage || agent.usage || null;
const tokens_input  = usage ? (usage.promptTokens ?? usage.input_tokens ?? null) : null;
const tokens_output = usage ? (usage.completionTokens ?? usage.output_tokens ?? null) : null;

// ---- 5) Objet de log -------------------------------------------------------
const mcp_call_count = toolsCalled.length;

return [{
  json: {
    execution_id: start.execution_id,
    request_ts:   start.started_at,
    session_id:   start.session_id,
    user_id:      start.user_id || null,
    question:     start.question,
    answer:       answer,
    model:        start.model,
    tokens_input:  tokens_input,
    tokens_output: tokens_output,
    started_at:   start.started_at,
    finished_at:  new Date(finishedMs).toISOString(),
    latency_ms:   finishedMs - Number(start.started_ms || finishedMs),
    // Indicateur central du chapitre : le modele s'est-il reellement ancre ?
    mcp_used:       mcp_call_count > 0 ? 1 : 0,
    mcp_call_count: mcp_call_count,
    mcp_tools:      Array.from(new Set(toolsCalled)),
    status:         answer ? 'ok' : 'empty_answer',
    error_message:  null,
    mitre_release_enterprise: dbEnterprise || 'unknown',
    mitre_release_ics:        dbIcs || 'unknown',
    mitre_ids: mitre_ids
  }
}];
